def canPartitionGrid(grid):
    def sweep(g):
        # Cuts after row i; discount a cell only from the top section if it is the larger one.
        m, n = len(g), len(g[0])
        total = sum(sum(row) for row in g)
        top = 0
        seen = set()
        for i in range(m - 1):
            top += sum(g[i])
            seen.update(g[i])
            diff = top - (total - top)
            if diff == 0:
                return True
            if diff > 0:
                h = i + 1
                if h >= 2 and n >= 2:
                    if diff in seen:
                        return True
                elif h == 1:
                    if diff == g[0][0] or diff == g[0][n - 1]:
                        return True
                else:  # n == 1, single column of height h >= 2
                    if diff == g[0][0] or diff == g[i][0]:
                        return True
        return False

    transposed = [list(col) for col in zip(*grid)]
    return (sweep(grid) or sweep(grid[::-1]) or
            sweep(transposed) or sweep(transposed[::-1]))
